207	static int battery_percent_from_mv(int mv)
208	{
209	  int i;
210	
211	  if (mv >= g_battery_curve[0].mv)
212	    {
213	      return 100;
214	    }
215	
216	  if (mv <= g_battery_curve[BATTERY_CURVE_LEN - 1].mv)
217	    {
218	      return 0;
219	    }
220	
221	  for (i = 1; i < (int)BATTERY_CURVE_LEN; i++)
222	    {
223	      if (mv >= g_battery_curve[i].mv)
224	        {
225	          const struct battery_point_s *hi = &g_battery_curve[i - 1];
226	          const struct battery_point_s *lo = &g_battery_curve[i];
227	          int span = hi->mv - lo->mv;
228	          int drop = hi->percent - lo->percent;
229	
230	          if (span <= 0)
231	            {
232	              return lo->percent;
233	            }
234	
235	          return lo->percent + (mv - lo->mv) * drop / span;
236	        }
237	    }
238	
239	  return 0;
240	}
